# -*- coding: utf-8 -*-
from future.utils import with_metaclass
from functools import partial
from abc import ABCMeta, abstractmethod
from collections import Counter, defaultdict
from collections.abc import Container
from taf.ul.ettf.logger.logger import custom_logger
from taf.ul.ettf.utils.functions import initialize_default
from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils import exception_causes


logger = custom_logger("Matchers")

MISSING_VALUE = 'missing'
OMIT_SUFFIX = ': omit'
CONTENT = 1


class MatchingError(BaseException):
    def __init__(self, mismatches):
        self.mismatches = mismatches

    def __str__(self):
        return '\n' + '\n'.join([str(m) for m in self.mismatches])


class MatchingResult(object):
    def __init__(self, mismatches=None):
        self.mismatches = initialize_default(mismatches, [])

    def __bool__(self):
        return not self.mismatches

    __nonzero__ = __bool__

    def __str__(self):
        return 'MatchingResult[Num: {}. M: [{}]]'.format(
            len(self.mismatches),
            ' | '.join([str(m) for m in self.mismatches]))

    def __repr__(self):
        return str(self)

    def __eq__(self, other):
        return self.mismatches == other.mismatches


class Mismatch(object):
    def __init__(self, msg, expected='', actual='', path=None, weight=1):
        path = initialize_default(path, [])
        self.path = path[:]
        self.weight = weight
        self.expected = str(expected)
        self.actual = str(actual)
        self.expected_value = expected
        self.actual_value = actual
        self.msg = msg.format(m=self)

    def __str__(self):
        if self.path:
            return '%s: %s' % (self.field(), self.msg)
        return self.msg

    def __repr__(self):
        return str(self)

    def __eq__(self, other):
        if not isinstance(other, Mismatch):
            return False
        return self.msg == other.msg and \
            self.field() == other.field() and \
            self.expected_value == other.expected_value and \
            self.actual_value == other.actual_value

    def __ne__(self, other):
        return not self.__eq__(other)

    def field(self):
        """Return the name of the mismatched field."""
        return ''.join(self.path).lstrip('.') if self.path else ''


class Matcher(with_metaclass(ABCMeta, object)):
    def __init__(self):
        self._name = ''
        self._callbacks = []

    def set_name(self, name):
        self._name = name

    def get_name(self):
        return self._name

    def append_callback(self, callback):
        if callback not in self._callbacks:
            self._callbacks.append(callback)

    def __len__(self):
        return self._get_corrected_length(self.expected_items)

    def _run_callbacks(self, value, mismatches):
        for callback in self._callbacks:
            callback(self, value, MatchingResult(mismatches))

    def match(self, value):
        """Raise MatchingError if value does not match the template."""
        mismatches = []
        try:
            self._do_match(value, mismatches)
        except MatchingError as e:
            mismatches.extend(e.mismatches)
        finally:
            self._run_callbacks(value, mismatches)

        if mismatches:
            raise MatchingError(mismatches)

    def matches(self, value):
        """Return True if value matches the template, and False otherwise."""
        try:
            self.match(value)
        except MatchingError as error:
            return MatchingResult(error.mismatches)
        else:
            return MatchingResult()

    @abstractmethod
    def _do_match(self, value, mismatches):
        pass

    @staticmethod
    def _get_corrected_length(item):
        try:
            return len(item)
        except (TypeError, AttributeError):
            return 1

    @classmethod
    def _get_length_diff(cls, expected, actual):
        return abs(cls._get_corrected_length(expected) - cls._get_corrected_length(actual))

    @classmethod
    def _compare_by_value(cls, expected, actual):
        if actual != expected:
            total_weight = 1 + cls._get_length_diff(expected, actual)
            raise MatchingError(
                [Mismatch('expected {m.expected}, got {m.actual}', expected, actual, weight=total_weight)])

    @classmethod
    def _match_or_compare(cls, expected, actual):
        try:
            expected.match(actual)
        except AttributeError:
            cls._compare_by_value(expected, actual)

    @classmethod
    def _is_matching(cls, expected, actual):
        try:
            cls._match_or_compare(expected, actual)
        except MatchingError:
            return False
        else:
            return True

    @staticmethod
    def _extend_paths(mismatches, path_item):
        for m in mismatches:
            m.path.insert(0, path_item)

    @classmethod
    def _accumulate_mismatches(cls, expected, actual, mismatches, path_item):
        try:
            cls._match_or_compare(expected, actual)
        except MatchingError as err:
            cls._extend_paths(err.mismatches, path_item)
            mismatches.extend(err.mismatches)
        return mismatches


class Omit(Matcher):
    def _do_match(self, value, mismatches):
        raise RuntimeError('Omit should never be used as a stand-alone matcher.')


class Value(Matcher):
    def __init__(self, expected):
        self.expected = expected
        super(Value, self).__init__()

    def __repr__(self):
        return str(self.expected)

    def _do_match(self, value, mismatches):
        self._compare_by_value(self.expected, value)


class DynamicValue(Matcher):
    def __init__(self):
        self.expected = None
        self.is_set = False
        super(DynamicValue, self).__init__()

    def _do_match(self, value, mismatches):
        if not self.is_set and not self.expected:
            self.expected = value
            self.is_set = True
        else:
            self._compare_by_value(self.expected, value)

        logger.info(('DynamicValue value:{} expected:{} is_set:{}'.format(value, self.expected, self.is_set)))


class StoredValue(Matcher):
    def __init__(self):
        self.expected = None
        self.is_set = False
        super(StoredValue, self).__init__()

    def _do_match(self, value, mismatches):
        if not self.is_set:
            self.expected = value
        else:
            self._compare_by_value(self.expected, value)

    def save(self):
        self.is_set = True

    def clear(self):
        self.is_set = False


class Range(Matcher):
    def __init__(self, lower, upper):
        if isinstance(lower, Container) or isinstance(upper, Container):
            raise TypeError('Bounds in Range should not be containers.')

        if lower.__class__ != upper.__class__:
            raise TypeError('Type mismatch between given bounds.')

        self.lower = lower
        self.upper = upper
        super(Range, self).__init__()

    @staticmethod
    def _get_type(obj):
        return obj.__class__.__name__

    def _do_match(self, value, mismatches):
        total_weight = 1 + self._get_length_diff(self.lower, value)

        if not isinstance(value, self.lower.__class__):
            error_message = 'type mismatch in range: expected {m.expected}, got {m.actual}'
            raise MatchingError([
                Mismatch(error_message, expected=self._get_type(self.lower),
                         actual=self._get_type(value), weight=total_weight)])

        if value < self.lower or value >= self.upper:
            error_message = 'expected value in range [%s, %s), got {m.actual}' % (self.lower, self.upper)
            expected_str = 'value in [%s, %s)' % (self.lower, self.upper)
            raise MatchingError([Mismatch(error_message, expected=expected_str, actual=value, weight=total_weight)])


class MultiMatcher(Matcher):
    def __init__(self, *args):
        self.expected_items = args
        super(MultiMatcher, self).__init__()

    def _check_length(self, value, mismatches):
        try:
            actual_len, expected_len = len(value), len(self.expected_items)
        except TypeError:
            raise MatchingError([Mismatch('should be a sequence', expected='sequence', actual=value, weight=2)])

        if actual_len != expected_len:
            total_weight = abs(expected_len - actual_len)
            mismatch = Mismatch('expected %d elements, got %d' % (expected_len, actual_len),
                                expected='length: %d' % expected_len, actual='length: %d' % actual_len,
                                weight=total_weight)
            mismatches.append(mismatch)

    def _do_match(self, value, mismatches):
        pass


class Seq(MultiMatcher):
    def _do_match(self, value, mismatches):
        self._check_length(value, mismatches)

        for index, (expected, actual) in enumerate(zip(self.expected_items, value)):
            if isinstance(expected, Omit):
                raise RuntimeError('Omit is not allowed in a sequence.')

            self._accumulate_mismatches(expected, actual, mismatches, '[%d]' % index)


class Contains(MultiMatcher):
    def _consistency_checks(self, value):
        try:
            if len(value) < len(self.expected_items):
                raise MatchingError([Mismatch('there are more expected items than number of items in sequence',
                                    expected='less items', actual=value, weight=2)])
        except TypeError:
            raise MatchingError([Mismatch('should be a sequence', expected='sequence', actual=value, weight=2)])

        for expected in self.expected_items:
            if isinstance(expected, Omit):
                raise RuntimeError('Omit is not allowed in a Contains matcher.')

    def _do_match(self, value, mismatches):
        self._consistency_checks(value)
        unmatched_items, unmatched_values = self._match_items(value)

        if not unmatched_items:
            return

        self._find_closest_mismatches(unmatched_items, unmatched_values, mismatches)

    def _match_items(self, value):
        items = list(self.expected_items[:])
        values = list(enumerate(value))

        for matcher in self.expected_items:
            matched_value = self._try_to_match(matcher, values)

            if matched_value:
                values.remove(matched_value)
                items.remove(matcher)
        return items, values

    def _try_to_match(self, matcher, values):
        for value in values:
            try:
                self._match_or_compare(matcher, value[CONTENT])
                return value
            except MatchingError:
                pass
        return None

    def _find_closest_mismatches(self, unmatched_items, unmatched_values, mismatches):
        for expected in unmatched_items:
            try:
                index, closest_matched_value = max(unmatched_values, key=partial(self._get_total_weight, expected))
                unmatched_values.remove((index, closest_matched_value))
                self._accumulate_mismatches(expected, closest_matched_value, mismatches, '[%d]' % index)
            except ValueError:
                mismatches.append(Mismatch('element not found', actual=unmatched_values[0][CONTENT], path=['[0]'], weight=0))

    def _get_total_weight(self, expected, value):
        all_mismatches = self._accumulate_mismatches(expected, value[CONTENT], [], "")
        return sum([m.weight + len(m.path) for m in all_mismatches])


class Perm(MultiMatcher):
    def _do_match(self, value, mismatches):
        self.items = list(self.expected_items[:])
        self._check_length(value, mismatches)

        for expected in self.expected_items:
            if isinstance(expected, Omit):
                raise RuntimeError('Omit is not allowed in a permutation.')

        self._match_items(value)
        self._find_closest_matches(mismatches)

    def _get_total_weight(self, unmatched_item, actual_item):
        return sum([m.weight for m in self._accumulate_mismatches(actual_item, unmatched_item, [], "")])

    def _match_items(self, value):
        self.unmatched = {}
        for index, actual in enumerate(value):
            try:
                matched_item = next(item for item in self.items if self._is_matching(item, actual))
                self.items.remove(matched_item)
            except StopIteration:
                self.unmatched[index] = actual

    def _find_closest_matches(self, mismatches):
        for index, unmatched_item in list(self.unmatched.items()):
            try:
                closest_match = min(self.items, key=partial(self._get_total_weight, unmatched_item))
                mismatches.append(Mismatch('element not found, closest match:', path=['[%d]' % index], weight=0))
                self._accumulate_mismatches(closest_match, unmatched_item, mismatches, '[%d]' % index)
            except ValueError:
                mismatches.append(Mismatch('element not found', actual=unmatched_item, path=['[%d]' % index], weight=0))


class Any(Matcher):
    def __init__(self, expected_items=None, **kwargs):
        expected_items = initialize_default(expected_items, {})
        self.expected_items = expected_items.copy()
        self.expected_items.update(kwargs)
        super(Any, self).__init__()

    @classmethod
    def _check_omitted(cls, key, struct, mismatches):
        try:
            if key in struct:
                mismatches.append(Mismatch('{m.actual} should be omitted', expected='%s%s' % (key, OMIT_SUFFIX), actual=key,
                                           weight=cls._get_corrected_length(struct[key])))
        except TypeError:
            pass

    @classmethod
    def _check_matching(cls, key, expected, struct, mismatches):
        try:
            actual = struct[key]
        except BaseException:
            mismatches.append(Mismatch('{m.expected} is missing', expected=key, actual=MISSING_VALUE,
                                       weight=cls._get_corrected_length(expected)))
        else:
            cls._accumulate_mismatches(expected, actual, mismatches, '.%s' % key)

    def _do_match(self, struct, mismatches):
        for key, expected in list(self.expected_items.items()):
            if isinstance(expected, Omit):
                self._check_omitted(key, struct, mismatches)
            else:
                self._check_matching(key, expected, struct, mismatches)

    def __add__(self, any_matcher):
        self._check_if_matchers_could_be_added(any_matcher)
        return self._combine_matchers(self, any_matcher)

    @classmethod
    def _check_if_matchers_could_be_added(cls, any_matcher):
        if not isinstance(any_matcher, Any):
            raise RuntimeError('You cannot add matchers with different types.')

    def _combine_matchers(self, matcher1, matcher2):
        combined_items = matcher1.expected_items.copy()
        for key, value in list(matcher2.expected_items.items()):
            if key not in list(combined_items.keys()):
                combined_items[key] = value
            elif isinstance(value, Any) and isinstance(combined_items[key], Any):
                combined_items[key] = self._combine_matchers(combined_items[key], value)
            else:
                raise RuntimeError('You cannot add matchers with common expected items.')

        return Any(combined_items)


class NamedMatcher(Any):
    def __init__(self, name, *args, **kwargs):
        self.name = name
        super(NamedMatcher, self).__init__(*args, **kwargs)


class ExpectationsBuilder(object):
    def __init__(self, name=None):
        self.name = name
        self.result = defaultdict(list)

    def append_element(self, element, key):
        self.result[key].append(element)

    def __call__(self, *args, **kwargs):
        return Any({self.name: MatchingExpectations(self.result)})


class WithCallback(Matcher):
    def __init__(self, matcher, callback):
        self.matcher = matcher
        self.callback = callback
        super(WithCallback, self).__init__()

    def _do_match(self, value, mismatches):
        try:
            self.matcher.match(value)
            self.callback()
        except MatchingError as e:
            mismatches.extend(e.mismatches)


class NotUniquePathError(LibraryError):
    def __init__(self, path):
        super(NotUniquePathError, self).__init__(exception_causes.PATH_NOT_UNIQUE, path)


class MatchingExpectations(Matcher):
    UNIQUE = 1

    def __init__(self, expectations_map):
        self.expectations_map = expectations_map
        super(MatchingExpectations, self).__init__()

    def __eq__(self, matcher):
        try:
            def equalable_dict(d):
                return {k: sorted(d[k], key=id) for k in d}
            return equalable_dict(self.expectations_map) == equalable_dict(matcher.expectations_map)
        except BaseException:
            pass
        return False

    def _do_match(self, value, mismatches):
        for name, matchers in self.expectations_map.items():
            if self._is_path(name):
                actual, path = self._eval_path(name, value)
            else:
                actual, path = self._eval_single_name(name, value)

            if self._name_is_not_found(actual, path) and not self._expected_omit(matchers):
                mismatches.append(Mismatch('{}: missing'.format(self._last_name_part(name)), expected=self._last_name_part(name),
                                           actual=MISSING_VALUE, path=[]))

            else:
                for expected in matchers:
                    if isinstance(expected, Omit):
                        if actual is not None:
                            mismatches.append(Mismatch('{m.actual} should be omitted', expected='%s%s' % (self._last_name_part(name), OMIT_SUFFIX),
                                                       actual=self._last_name_part(name),
                                                       weight=self._get_corrected_length(actual), path=self._format_path(path)))
                    else:
                        if actual is None:
                            mismatches.append(Mismatch('{m.expected} is missing', expected=self._last_name_part(name), actual=MISSING_VALUE,
                                                       weight=self._get_corrected_length(expected), path=self._format_path(path)))
                        else:
                            self._accumulate_mismatches(expected, actual, mismatches, '.' + '.'.join(reversed(path)))

    @staticmethod
    def _format_path(path):
        return ['.{}'.format(elem) for elem in reversed(path)]

    @staticmethod
    def _last_name_part(name):
        return name.split('.')[-1]

    @staticmethod
    def _name_is_not_found(actual, path):
        return actual is None and path == []

    @staticmethod
    def _expected_omit(matchers):
        for expected in matchers:
            if isinstance(expected, Omit):
                return True
        return False

    @staticmethod
    def _is_path(name):
        PATH_SEPARATOR = '.'
        return PATH_SEPARATOR in name

    def _eval_path(self, name, value):
        path_elems = name.split('.')
        name = path_elems[0]
        last_name = path_elems[-1]

        self._assert_that_path_is_unique(path_elems, value)
        actual, path = self._find(value, name)
        actual, subpath = self._find(actual, last_name)
        return actual, subpath + path

    def _eval_single_name(self, name, value):
        self._assert_that_name_is_unique(name, value)
        return self._find(value, name)

    def _assert_that_name_is_unique(self, name, value):
        all_names = Counter(self._all_names(value))

        if all_names[name] > self.UNIQUE:
            raise NotUniquePathError('Given path ({}) is not unique'.format(name))

    def _assert_that_path_is_unique(self, names, value):
        for name in names:
            try:
                self._assert_that_name_is_unique(name, value)
                return
            except NotUniquePathError:
                pass
        raise NotUniquePathError('Given path ({}) is not unique'.format('.'.join(names)))

    def _find(self, node, name):
        return self._find_with_path(node, name, [])

    def _find_with_path(self, node, name, path):
        if not isinstance(node, dict):
            return None, []

        if name in node:
            path.append(name)
            return node[name], path

        found, found_path = None, []

        for k, v in node.items():
            found, found_path = self._find_with_path(v, name, path)
            if found is not None:
                path.append(k)
                break

        return found, found_path

    def _all_names(self, node):
        if not isinstance(node, dict):
            return []

        names = list(node.keys())

        for subnode in list(node.values()):
            names.extend(self._all_names(subnode))

        return names


def first_matching(items, template, default=None):
    """Return the first item that matches the template, or default when no such item exists."""
    matching = [e for e in items if template.matches(e)]
    return matching[0] if matching else default
